import subprocess,statistics,pathlib,fcntl,json,random
p=pathlib.Path(__file__).parent
modes=['typical_sparse','typical_dense','chain','bipartite','general','sets','submod','incremental','reuse','unary_large','empty','one']
variants=['baseline','reserve','zero','both']
configs={'gcc_native':(['/usr/bin/g++'],['-march=native']),'gcc_znver2':(['/usr/bin/g++'],['-march=znver2']),'clang':(['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'],[])}
rows=[]
for config,(compiler,flags) in configs.items():
 for name in variants:
  cmd=['taskset','-c','7']+compiler+['-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',f'-DSIRKIT_PROJECT_TEST_HEADER="{p/name}.cpp"','Verify/current/tests/project_selection_performance_benchmark.cpp','-o',str(p/f'{config}_{name}')]+flags
  subprocess.run(cmd,check=True)
 print('compiled',config,flush=True)
with open('/tmp/sirkit_performance_cpu16.lock','w') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for config in configs:
  for rep in range(5):
   for mode in modes:
    names=variants.copy();random.Random(rep*991+len(mode)).shuffle(names)
    for name in names:
     out=subprocess.check_output(['taskset','-c','16',str(p/f'{config}_{name}'),mode],text=True).split()
     rows.append({'config':config,'rep':rep,'mode':mode,'name':name,'ms':float(out[0]),'checksum':out[1]})
  (p/'matrix_raw.json').write_text(json.dumps(rows,indent=2))
  for mode in modes:
   x={v:statistics.median(r['ms'] for r in rows if r['config']==config and r['mode']==mode and r['name']==v) for v in variants}
   assert len({r['checksum'] for r in rows if r['config']==config and r['mode']==mode})==1
   print(config,mode,{v:round(x[v]/x['baseline'],3) for v in variants},flush=True)

