import subprocess,statistics,pathlib,fcntl,json,random
p=pathlib.Path(__file__).parent
modes=['typical_sparse','typical_dense','chain','bipartite','general','sets','submod','incremental','reuse','unary_large','empty','one']
variants=['baseline','reserve','small','depthbound'];configs=['gcc','gcc_native','gcc_znver2','clang'];rows=[]
def exe(c,v):return p/(v if c=='gcc' and v in ['baseline','reserve'] else f'{c}_{v}')
with open('/tmp/sirkit_performance_cpu16.lock','w') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for config in configs:
  for rep in range(7):
   for mode in modes:
    names=variants.copy();random.Random(rep*379+len(mode)).shuffle(names)
    for name in names:
     out=subprocess.check_output(['taskset','-c','16',str(exe(config,name)),mode],text=True).split()
     rows.append({'config':config,'rep':rep,'mode':mode,'name':name,'ms':float(out[0]),'checksum':out[1]})
  (p/'reserve_matrix_raw.json').write_text(json.dumps(rows,indent=2))
  for mode in modes:
   x={v:statistics.median(r['ms'] for r in rows if r['config']==config and r['mode']==mode and r['name']==v) for v in variants}
   assert len({r['checksum'] for r in rows if r['config']==config and r['mode']==mode})==1
   print(config,mode,{v:round(x[v]/x['baseline'],3) for v in variants},flush=True)
